<?php
declare(strict_types=1);
function current_user(): ?array { return $_SESSION['user']??null; }
function require_auth(): array { $u=current_user(); if(!$u)respond(['error'=>'Authentication required'],401); return $u; }
function require_permission(string $p): array { $u=require_auth(); if($u['role']==='Administrator')return $u; if(!in_array($p,$u['permissions']??[],true))respond(['error'=>'Permission denied'],403); return $u; }
function user_payload(int $id): array { $q=db()->prepare('SELECT u.id,u.full_name,u.email,u.phone,u.staff_position,r.name role,u.status,u.must_change_password FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=?'); $q->execute([$id]); $u=$q->fetch(); if(!$u)respond(['error'=>'Account not found'],404); $q=db()->prepare('SELECT p.code FROM user_permissions up JOIN permissions p ON p.id=up.permission_id WHERE up.user_id=? ORDER BY p.code'); $q->execute([$id]); $u['permissions']=array_column($q->fetchAll(),'code');$q=db()->prepare('SELECT branch_id FROM user_branches WHERE user_id=? ORDER BY branch_id');$q->execute([$id]);$u['branch_ids']=array_map('intval',array_column($q->fetchAll(),'branch_id'));return $u; }
function user_branch_ids(array $user): array { if(($user['role']??'')==='Administrator')return array_map('intval',array_column(db()->query('SELECT id FROM branches WHERE active=1 ORDER BY id')->fetchAll(),'id'));$q=db()->prepare('SELECT ub.branch_id FROM user_branches ub JOIN branches b ON b.id=ub.branch_id WHERE ub.user_id=? AND b.active=1 ORDER BY ub.branch_id');$q->execute([$user['id']]);return array_map('intval',array_column($q->fetchAll(),'branch_id')); }
function active_branch_id(array $user): int { if(($user['role']??'')==='Administrator'){$id=(int)($_SESSION['active_branch_id']??0);if($id)return $id;$q=db()->query('SELECT id FROM branches WHERE active=1 ORDER BY id LIMIT 1');return (int)$q->fetchColumn();}$allowed=user_branch_ids($user);$id=(int)($_SESSION['active_branch_id']??0);if($id&&in_array($id,$allowed,true))return $id;if(!$allowed)respond(['error'=>'This staff account has no active branch assignment'],403);$_SESSION['active_branch_id']=$allowed[0];return $allowed[0]; }
function require_branch_access(array $user,int $branchId): void { if($branchId<1)respond(['error'=>'Choose a branch'],422);if(($user['role']??'')==='Administrator')return;if(!in_array($branchId,user_branch_ids($user),true))respond(['error'=>'You do not have access to this branch'],403); }
function catalog_products(bool $all=false): array { $sql='SELECT p.id,p.code,p.name,p.description,p.units_per_box,p.allow_individual,c.name category FROM products p LEFT JOIN product_categories c ON c.id=p.category_id WHERE p.is_active=1'; if(!$all)$sql.=' AND p.is_public=1'; return db()->query($sql.' ORDER BY p.name LIMIT 250')->fetchAll(); }
